import assert from "node:assert/strict";
import {readFileSync,writeFileSync} from "node:fs";
import {createHash} from "node:crypto";
import ts from "typescript";
import {environment} from "../barrel-catalog-teacher-v11-20261118/profiles";
const base=import.meta.dir+"/../barrel-catalog-teacher-v11-20261118/sources/common/",sha=(b:Buffer)=>createHash("sha256").update(b).digest("hex");
const driverRaw=readFileSync(base+"src/simulation/search_driver.ts"),engineRaw=readFileSync(base+"src/engine/action_engine.ts"),candidateRaw=readFileSync(base+"src/ai/candidates.ts");
const sf=ts.createSourceFile("search_driver.ts",driverRaw.toString(),ts.ScriptTarget.Latest,true),ef=ts.createSourceFile("action_engine.ts",engineRaw.toString(),ts.ScriptTarget.Latest,true);
const found:ts.Node[]=[];function visit(n:ts.Node,cb:(n:ts.Node)=>void){cb(n);ts.forEachChild(n,c=>visit(c,cb));}
visit(sf,n=>{if(ts.isClassDeclaration(n)&&n.name?.text==="SearchDriver")found.push(n);});assert.equal(found.length,1);const klass=found[0]as ts.ClassDeclaration;
const method=(name:string)=>{const m=klass.members.find(m=>ts.isMethodDeclaration(m)&&m.name.getText(sf)===name)as ts.MethodDeclaration;assert(m?.body);return m;};
const choose=method("chooseSearchDecision"),outer=method("chooseDecision"),squeeze=(n:ts.Node)=>n.getText(sf).replace(/\s+/g,"");
function bareAssignments(body:ts.Node,name:string){const out:ts.BinaryExpression[]=[];visit(body,n=>{if(ts.isBinaryExpression(n)&&["=","+=","-=","*=","/=","??=","&&=","||="].includes(n.operatorToken.getText(sf))&&ts.isIdentifier(n.left)&&n.left.text===name)out.push(n);});return out;}
const candidateAssignments=bareAssignments(choose.body!,"candidates");assert.equal(candidateAssignments.length,1);const assignment=candidateAssignments[0];
assert.equal(squeeze(assignment),"candidates=[...candidates,expandedProductiveFallback]");
function positiveConjunct(n:ts.Expression,name:string):boolean{return ts.isIdentifier(n)&&n.text===name||ts.isParenthesizedExpression(n)&&positiveConjunct(n.expression,name)||ts.isBinaryExpression(n)&&n.operatorToken.kind===ts.SyntaxKind.AmpersandAmpersandToken&&(positiveConjunct(n.left,name)||positiveConjunct(n.right,name));}
let node:ts.Node|undefined=assignment.parent,positiveGuard=false;const parents:string[]=[];
while(node&&node!==choose){if(ts.isIfStatement(node)){parents.push(node.expression.getText(sf));positiveGuard||=positiveConjunct(node.expression,"prioritizeProductiveActions");}node=node.parent;}
assert(positiveGuard);
let predicate:ts.VariableDeclaration|undefined;visit(choose.body!,n=>{if(ts.isVariableDeclaration(n)&&ts.isIdentifier(n.name)&&n.name.text==="prioritizeProductiveActions")predicate=n;});assert(predicate?.initializer);
assert.equal(squeeze(predicate.initializer),"isV08Search&&!deliberateBarrel&&V08_FORCE_PRODUCTIVE_INCUMBENT_KINDS.has(incumbentKind)");
const directMutators:string[]=[];visit(choose.body!,n=>{if(ts.isCallExpression(n)&&ts.isPropertyAccessExpression(n.expression)&&ts.isIdentifier(n.expression.expression)&&n.expression.expression.text==="candidates"&&["push","pop","shift","unshift","splice","sort","reverse","copyWithin","fill"].includes(n.expression.name.text))directMutators.push(n.getText(sf));});assert.deepEqual(directMutators,[]);
const rewrites=bareAssignments(outer.body!,"incumbent");assert.equal(rewrites.length,1);assert(ts.isArrayLiteralExpression(rewrites[0].right));assert.equal(rewrites[0].right.elements.length,1);
assert.equal(squeeze(rewrites[0].right),'[{type:"wait_turn",unitId:unit.getId()}]');
let force:ts.VariableDeclaration|undefined;visit(sf,n=>{if(ts.isVariableDeclaration(n)&&ts.isIdentifier(n.name)&&n.name.text==="V08_FORCE_PRODUCTIVE_INCUMBENT_KINDS")force=n;});assert(force?.initializer&&ts.isNewExpression(force.initializer));
const arg=force.initializer.arguments?.[0];assert(arg&&ts.isArrayLiteralExpression(arg));const forceKinds=arg.elements.map(x=>{assert(ts.isStringLiteral(x));return x.text;});assert.deepEqual(forceKinds,["idle","defend","mine"]);assert(!forceKinds.includes("wait"));
function rootName(n:ts.Expression):string|undefined{if(ts.isIdentifier(n))return n.text;if(ts.isPropertyAccessExpression(n)||ts.isElementAccessExpression(n))return rootName(n.expression);return undefined;}
const actionWrites:string[]=[];visit(ef,n=>{if(ts.isBinaryExpression(n)&&["=","+=","-=","*=","/=","??=","&&=","||="].includes(n.operatorToken.getText(ef))&&rootName(n.left)==="action"&&!ts.isIdentifier(n.left))actionWrites.push(n.getText(ef));});assert.deepEqual(actionWrites,[]);
assert.equal(environment.V07_SEARCH,"1");assert.equal(environment.SEARCH_A19_MELEE_BARREL_DELIBERATION,"1");assert(environment.SEARCH_VERSIONS.split(",").includes("v0.8"));
const result={passed:true,schema:"barrel-initial-catalog-source-contract-v1",parserVersion:ts.version,sourceFiles:[{path:"src/simulation/search_driver.ts",sha256:sha(driverRaw)},{path:"src/engine/action_engine.ts",sha256:sha(engineRaw)},{path:"src/ai/candidates.ts",sha256:sha(candidateRaw)}],
 onlyPostEnumerationDirectListAppend:squeeze(assignment),appendEnclosingConditions:parents,appendRequiresProductiveTier:true,productiveTierDisabledForDeliberateBarrels:true,
 onlyOuterIncumbentRewrite:"wait_turn",waitNotInForcedProductiveKinds:true,noDirectListMutators:true,noActionParameterPropertyAssignmentsInEngine:true,
 frozenNativeV08SearchAndBarrelDeliberationEnabled:true,
 dataRequirements:["Eligible observed cleanup is a melee deployment-barrel fallback with pre-cleanup movement/hold and no explicit combat/spell.","First native input, when present, starts with the cleanup incumbent or the one Healer wait rewrite. Missing native catalogs remain explicit abstentions.","No post-probe candidate append can occur on these paths: a retained barrel disables productive tier; a wait rewrite is outside its hard-passive kind set.","Only first native input metadata is admitted. Later shortlist outputs, query scores, action attempts and actual choices are excluded from X."],
 limitation:"These source-bound facts plus full functional/cold controls and complete data checks establish this input contract for the frozen implementation; this is not a general transitive-purity proof or current-v12 qualification.",
 modelFitted:false,defaultChanged:false};
writeFileSync(import.meta.dir+"/source-contract.json",JSON.stringify(result,null,2)+"\n",{flag:"wx"});console.log(JSON.stringify(result));

/** One complete, source-bound assembly. No class/performance summaries, fitter or policy. */
import assert from "node:assert/strict";
import {createHash} from "node:crypto";
import {appendFileSync,closeSync,createReadStream,mkdirSync,openSync,readFileSync,readdirSync,writeFileSync} from "node:fs";
import {createInterface} from "node:readline";
import {createGunzip,gzipSync} from "node:zlib";
import {FEATURE_NAMES,observationInput,project,actionKey} from "../barrel-public-action-representation-v2-20261118/representation";
const p=import.meta.dir,parent=p+"/../barrel-catalog-teacher-v11-20261118",read=(f:string)=>JSON.parse(readFileSync(f,"utf8")),hash=(v:unknown)=>createHash("sha256").update(JSON.stringify(v)).digest("hex"),sha=(b:Buffer)=>createHash("sha256").update(b).digest("hex");
const raw=readFileSync(p+"/registration.json"),reg=JSON.parse(raw.toString()),seal=sha(raw);for(const f of reg.files)assert.equal(sha(readFileSync(p+"/"+f.path)),f.sha256,f.path);
assert(Date.now()/1000<reg.deadlineUnix);
const prefix=read(p+"/../barrel-native-catalog-replay-functional-v2-20261118/catalog-independent-verification.json");assert(prefix.verificationPassed&&prefix.admissionPassed);
assert.equal(sha(readFileSync(parent+"/registration.json")),reg.parentRegistrationSha256);
const complete=read(parent+"/complete-verification.json"),independent=read(parent+"/independent-complete-verification.json");assert(complete.passed&&independent.passed);assert.equal(complete.registrationSha256,reg.parentRegistrationSha256);assert.equal(independent.registrationSha256,reg.parentRegistrationSha256);
for(const f of complete.rawFiles)assert.equal(sha(readFileSync(parent+"/"+f.path)),f.sha256,f.path);
const contract=read(p+"/source-contract.json");assert(contract.passed);for(const f of contract.sourceFiles)assert.equal(sha(readFileSync(parent+"/sources/common/"+f.path)),f.sha256,f.path);
const casebook=read(parent+"/cases-all.json"),expected=new Map<string,any>(casebook.map((j:any)=>[j.caseId,j]));assert.equal(expected.size,6048);
const features=[...FEATURE_NAMES,"outsideOption"],outsideKeep=features.map(n=>n.startsWith("actor.")||n.startsWith("allies.")||n.startsWith("enemies.")||n.startsWith("map.")||n==="lap"||n==="activeTimeDenial");assert.equal(features.length,191);
const out=p+"/prepared";mkdirSync(out);for(const fold of["train","validation","test"])closeSync(openSync(out+"/"+fold+".jsonl.gz","wx"));
const control=new Map<string,any>(),seen=new Set<string>(),families=new Map<string,string>(),caseRows:any[]=[],violations:any[]=[];let rows=0;
async function* lines(file:string){for await(const line of createInterface({input:createReadStream(file).pipe(createGunzip()),crlfDelay:Infinity}))yield JSON.parse(line);}
for(const host of["local","puffalo"]){
 const stem="collection-"+host;
 for(const f of readdirSync(parent+"/"+stem).filter(f=>/^worker-\d+\.jsonl\.gz$/.test(f)))for await(const r of lines(parent+"/"+stem+"/"+f)){
  const j=expected.get(r.caseId);assert(j);assert(!control.has(r.caseId));assert.equal(j.assignedHost,host);control.set(r.caseId,{labels:r.labels,labelsDigest:r.labelsDigest,labelPayloadSha256:r.labelPayloadSha256});
 }
}
assert.equal(control.size,6048);
const explicit=new Set(["melee_attack","range_attack","area_throw_attack","cast_spell","obstacle_attack"]);
for(const host of["local","puffalo"]){
 const stem="collection-"+host;
 for(const f of readdirSync(parent+"/"+stem).filter(f=>/^worker-\d+-labels\.(train|validation|test)\.jsonl\.gz$/.test(f)).sort())for await(const r of lines(parent+"/"+stem+"/"+f)){
  assert(Date.now()/1000<reg.deadlineUnix);assert(r.jobId.startsWith("collection/"));const caseId=r.jobId.slice(11),j=expected.get(caseId),c=control.get(caseId);assert(j&&c);assert(!seen.has(caseId));seen.add(caseId);
  assert.equal(j.assignedHost,host);assert.equal(r.familyId,j.familyId);assert.equal(r.fold,j.fold);assert.equal(hash(r),c.labelPayloadSha256);assert.equal(hash(r.labels),c.labelsDigest);assert.equal(r.labels.length,c.labels);
  const prior=families.get(r.familyId);if(prior)assert.equal(prior,r.fold);else families.set(r.familyId,r.fold);
  caseRows.push({caseId,familyId:r.familyId,fold:r.fold,observations:r.labels.length,sourceLabelPayloadSha256:c.labelPayloadSha256});
  for(const o of r.labels){
   const rowId=caseId+"/"+o.ordinal,input=observationInput(o),actor=input.publicState.units.find((u:any)=>u.id===input.actorId);assert(actor);
   const fail=(condition:boolean,reason:string)=>{if(!condition)violations.push({rowId,reason});};
   fail(actor.attackSelection!==2,"recorded ranged actor at melee-only boundary");fail(!o.before.some((a:any)=>explicit.has(a.type))&&o.before.some((a:any)=>["move_unit","wait_turn","defend_turn"].includes(a.type)),"invalid pre-cleanup eligibility");
   const strike=o.cleanup.find((a:any)=>a.type==="obstacle_attack"),g=input.publicState.gridGeometry;
   const cell=strike?{x:Math.floor((strike.targetPosition.x+g.maxX)/g.cellSize),y:Math.floor(strike.targetPosition.y/g.cellSize)}:undefined;
   fail(!!strike&&strike.attackerId===o.unitId&&input.publicState.barrels.some((b:any)=>b.cell.x===cell!.x&&b.cell.y===cell!.y),"not a deployment-barrel incumbent");
   if(input.nativeCatalog.length){
    const first=input.nativeCatalog[0],root=o.rootRecords[0],isOriginal=actionKey(first.actions)===actionKey(o.cleanup),isWaitRewrite=actor.name==="Healer"&&first.actions.length===1&&first.actions[0].type==="wait_turn"&&first.actions[0].unitId===o.unitId;
    fail(root.version==="v0.8"&&first.kind==="incumbent"&&actionKey(root.rawIncumbent)===actionKey(o.cleanup)&&(isOriginal||isWaitRewrite),"initial catalog is outside the proven barrel/Healer-wait source paths");
    for(const candidate of input.nativeCatalog){
     fail(!!candidate.features&&Object.values(candidate.features).every(v=>typeof v==="number"&&Number.isFinite(v)),"invalid static candidate metadata");
     fail(candidate.features?.lap===o.lap,"static metadata lap does not match pre-decision state");
    }
   }
   const proposals=project(input),actual=actionKey(o.chosenDecision),target=proposals.findIndex(p=>p.key===actual),cleanupIndex=proposals.findIndex(p=>p.isCleanup),beforeIndex=proposals.findIndex(p=>p.isBefore),outsideIndex=proposals.length;
   assert(cleanupIndex>=0&&beforeIndex>=0&&cleanupIndex!==beforeIndex);const valid=proposals.map(p=>!p.blockedByPublicMask);valid.push(true);
   fail(target<0||valid[target],"actual accepted teacher choice marked invalid by public mask");
   const matrix=proposals.map(p=>[...p.features,0]),outside=matrix[0].map((v,i)=>outsideKeep[i]?v:0);outside[outside.length-1]=1;matrix.push(outside);
   assert(matrix.every(x=>x.length===191&&x.every(Number.isFinite)));
   const row={schema:"barrel-static-catalog-learning-row-v2",rowId,familyId:r.familyId,fold:r.fold,
    targetIndex:target<0?outsideIndex:target,cleanupIndex,beforeIndex,outsideIndex,valid,
    allowInference:input.nativeCatalog.length>0&&!proposals.some(p=>p.requiresUnavailablePublicRecipient),features:matrix};
   appendFileSync(out+"/"+r.fold+".jsonl.gz",gzipSync(JSON.stringify(row)+"\n",{level:1}));rows++;
  }
 }
}
assert.equal(seen.size,6048);assert.equal(families.size,1512);assert.equal(rows,complete.collectionObservations);
const inventory=["train","validation","test"].map(fold=>{const raw=readFileSync(out+"/"+fold+".jsonl.gz");return{path:"prepared/"+fold+".jsonl.gz",bytes:raw.length,sha256:sha(raw)};});
writeFileSync(out+"/feature-names.json",JSON.stringify(features,null,2)+"\n",{flag:"wx"});writeFileSync(out+"/case-ledger.json",JSON.stringify(caseRows,null,2)+"\n",{flag:"wx"});writeFileSync(out+"/input-violations.json",JSON.stringify(violations,null,2)+"\n",{flag:"wx"});
const result={passed:violations.length===0,registrationSha256:seal,parentRegistrationSha256:reg.parentRegistrationSha256,
 completeSourceCases:seen.size,completeSourceFamilies:families.size,observations:rows,featureCount:191,inputViolations:violations.length,
 allFamiliesKeepOriginalProspectiveFolds:true,allZeroObservationCasesRetained:true,allMissingCatalogAndRecipientCasesRetainedAsAbstentions:true,
 allOutsideCatalogActualChoicesRetainedAsOutsideLabels:true,heldoutClassOrPerformanceMetricsNotInspected:true,modelFitted:false,defaultChanged:false,newIndependentStrengthSamples:0,
 files:[...inventory,...["feature-names.json","case-ledger.json","input-violations.json"].map(f=>({path:"prepared/"+f,sha256:sha(readFileSync(out+"/"+f))}))]};
writeFileSync(p+"/assembly-result.json",JSON.stringify(result,null,2)+"\n",{flag:"wx"});console.log(JSON.stringify({...result,files:undefined}));
